RED.defaultFlows = (function () {

    var defaultFlowFiles = [
        "subflows/fully-automated.json",
        "subflows/partially-automated.json",
        "subflows/human-intervention-workflow.json",
    ];

    // open sidebar at application start
    var SIDEBAR_TAB_ID = "models";
    var sidebarOpened = false;

    function openModelsSidebar(attempts) {
        if (sidebarOpened) { return; }
        try {
            RED.sidebar.show(SIDEBAR_TAB_ID);
            sidebarOpened = true;
        } catch (e) {
            if (attempts > 0) {
                setTimeout(function () { openModelsSidebar(attempts - 1); }, 300);
            }
        }
    }
    function init() {
        RED.events.on("runtime-state", function () {

            defaultFlowFiles.forEach(function (file) {
                $.getJSON(file, function (flowJson) {
                    var subflowNode = flowJson.find(function (n) { return n.type === "subflow"; });
                    if (subflowNode && !RED.nodes.subflow(subflowNode.id)) {
                        RED.view.importNodes(flowJson, { generateIds: false, addFlow: true });
                    }
                    RED.workspaces.remove();
                }).fail(function (err) {
                });
            });
        });
        openModelsSidebar(20);
    }

    return {
        init: init
    };

})();